// ბოლო 200 სიტყვა ინახება, რომ არ განმეორდეს (მუშაობს გააქტიურებულ workflow-ში)
const st = $getWorkflowStaticData('global');
const used = st.used || [];
const cfg = $input.first().json;
return [{ json: { ...cfg, avoid: used.slice(-120).join(', ') } }];

const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const r = JSON.parse($json.choices[0].message.content);
const cfg = $('პარამეტრები').first().json;
const st = $getWorkflowStaticData('global');
st.used = [...(st.used || []), r.word].slice(-200);
const caption =
  `🌅 <b>დღის სიტყვა</b> · ${esc(cfg.level)}\n\n` +
  `🔤 <b>${esc(r.word)}</b> ${esc(r.ipa)}\n` +
  `🇬🇪 ${esc(r.meaning_ka)} <i>(${esc(r.pos_ka)})</i>\n\n` +
  `💬 <i>${esc(r.example)}</i>\n${esc(r.example_ka)}\n\n` +
  `🧩 ${esc(r.phrase)} — ${esc(r.phrase_ka)}\n` +
  `💡 ${esc(r.tip_ka)}\n\n` +
  `✍️ დღეს ეს სიტყვა ერთ წინადადებაში გამოიყენე და Mr. Ben-ს მისწერე!`;
return [{ json: { ...r, caption: caption.slice(0, 1024), speech: `${r.word}. ${r.example}`, chat_id: cfg.chat_id } }];
